INSERT INTO products (id,slug,name,sku,short_description,description,price,regular_price,currency,in_stock,is_featured,datasheet_url,wp_permalink) VALUES (19863,'sp-4-mdvt-8','SP-4-MDVT-8','SP-4-MDVT-8','ซีรีส์ SP / EP / AP เป็นหัวต่อลำโพง (Loudspeaker connector) มีให้เลือกแบบ 2 หรือ 4 ขั้ว ตัวเรือน Thermoplastic ทนทาน พร้อมขั้วสัมผัสกระแสสูง ส่งสัญญาณได้ไม่ผิดเพี้ยน เข้ากับมาตฐานห…','<p>ซีรีส์ SP / EP / AP เป็นหัวต่อลำโพง (Loudspeaker connector) มีให้เลือกแบบ 2 หรือ 4 ขั้ว ตัวเรือน Thermoplastic ทนทาน พร้อมขั้วสัมผัสกระแสสูง ส่งสัญญาณได้ไม่ผิดเพี้ยน เข้ากับมาตฐานหัวต่อลำโพงอุตสาหกรรม</p><p><strong>ซีรีส์:</strong> SP Series Loudspeaker Cable Connectors</p><h3>คุณสมบัติเด่น</h3><ul><li>ขั้วสัมผัสกระแสสูง ทองแดงชุบเงิน</li><li>ตัวเรือน Thermoplastic ทนทาน</li><li>ระบบล็อกแบบ Quick release ป้องกันการสั่นสะเทือน</li><li>มีให้เลือก 2 และ 4 ขั้ว</li></ul><p class="muted">ข้อมูลเพิ่มเติมและแบบวาด (Drawing) / ไฟล์ 3D: SP-4-MDVT-8 — ดูได้จากแคตตาล็อกสินค้าด้านล่าง</p>',0,0,'THB',1,1,'https://www.aph-ita.co.th/wp-content/uploads/2026/03/Amphenol_Loader_speaker.pdf','https://www.aph-ita.co.th/product/sp-4-mdvt-8/');
