INSERT INTO products (id,slug,name,sku,short_description,description,price,regular_price,currency,in_stock,is_featured,datasheet_url,wp_permalink) VALUES (16425,'acpr-syl','ACPR-SYL','ACPR-SYL','หัวต่อ RCA ของ Amphenol ซีรีส์ AC ผลิตจากโลหะคุณภาพสูง มีทั้งแบบบัดกรีและแบบขันเกลียว พร้อมให้เลือกหลายสีตามมาตรฐานสัญญาณ (แดง/ขาว/เหลือง) และแบบตัวผู้–ตัวเมีย…','<p>หัวต่อ RCA ของ Amphenol ซีรีส์ AC ผลิตจากโลหะคุณภาพสูง มีทั้งแบบบัดกรีและแบบขันเกลียว พร้อมให้เลือกหลายสีตามมาตรฐานสัญญาณ (แดง/ขาว/เหลือง) และแบบตัวผู้–ตัวเมีย</p><p><strong>ซีรีส์:</strong> RCA</p><h3>คุณสมบัติเด่น</h3><ul><li>ตัวเรือนโลหะชุบนิกเกิล</li><li>มีให้เลือกทั้งแบบบัดกรีและขันเกลียว</li><li>หลากสีตามมาตรฐานสัญญาณ</li><li>มีทั้งตัวผู้และตัวเมีย</li></ul><p class="muted">ข้อมูลเพิ่มเติมและแบบวาด (Drawing) / ไฟล์ 3D: ACPR-SYL — ดูได้จากแคตตาล็อกสินค้าด้านล่าง</p>',0,0,'THB',1,0,'https://www.aph-ita.co.th/wp-content/uploads/2026/03/Amphenol_RCA.pdf','https://www.aph-ita.co.th/product/acpr-syl/');
