INSERT INTO products (id,slug,name,sku,short_description,description,price,regular_price,currency,in_stock,is_featured,datasheet_url,wp_permalink) VALUES (16185,'mp-41-series-th29-1','MP-41 Series – TH29-1','TH29-1','หัวต่อ Multipin MP Series สำหรับงานที่ต้องเดินสายสัญญาณหลายชุดในเส้นเดียว ช่วยลดเวลาติดตั้งและลดความผิดพลาดในการต่อสาย เหมาะกับงานเวที งานอีเวนต์ และงานติดตั้งถาวร…','<p>หัวต่อ Multipin MP Series สำหรับงานที่ต้องเดินสายสัญญาณหลายชุดในเส้นเดียว ช่วยลดเวลาติดตั้งและลดความผิดพลาดในการต่อสาย เหมาะกับงานเวที งานอีเวนต์ และงานติดตั้งถาวร</p><p><strong>ซีรีส์:</strong> Multipin</p><h3>คุณสมบัติเด่น</h3><ul><li>รวมสายหลายชุดในหัวเดียว</li><li>ตัวล็อกแบบเกลียวแน่นหนา</li><li>อะไหล่และไกด์ให้เลือกครบ</li><li>เหมาะกับงานเวทีและงานติดตั้ง</li></ul><p class="muted">ข้อมูลเพิ่มเติมและแบบวาด (Drawing) / ไฟล์ 3D: TH29-1 — ดูได้จากแคตตาล็อกสินค้าด้านล่าง</p>',0,0,'THB',1,0,'https://www.aph-ita.co.th/wp-content/uploads/2026/03/Amphenol_multipin.pdf','https://www.aph-ita.co.th/product/mp-41-series-th29-1/');
