INSERT INTO products (id,slug,name,sku,short_description,description,price,regular_price,currency,in_stock,is_featured,datasheet_url,wp_permalink) VALUES (11543,'hpt-3-mdw','HPT-3-MDW – Power Connector','Power Connector','หัวต่อไฟ AC ซีรีส์ HP และ HPT สำหรับงานเครื่องเสียงมืออาชีพ รับกระแสได้สูง พร้อมระบบล็อกที่ป้องกันการหลุดระหว่างใช้งาน เหมาะกับงานเวทีและงานติดตั้ง…','<p>หัวต่อไฟ AC ซีรีส์ HP และ HPT สำหรับงานเครื่องเสียงมืออาชีพ รับกระแสได้สูง พร้อมระบบล็อกที่ป้องกันการหลุดระหว่างใช้งาน เหมาะกับงานเวทีและงานติดตั้ง</p><p><strong>ซีรีส์:</strong> HPT Series</p><h3>คุณสมบัติเด่น</h3><ul><li>รับกระแสไฟได้สูง</li><li>ระบบล็อกแบบ Twist-lock</li><li>ตัวเรือนทนความร้อน</li><li>มีทั้งแบบตัวผู้ ตัวเมีย และฝาครอบ</li></ul><p class="muted">ข้อมูลเพิ่มเติมและแบบวาด (Drawing) / ไฟล์ 3D: Power Connector — ดูได้จากแคตตาล็อกสินค้าด้านล่าง</p>',0,0,'THB',1,1,'https://www.aph-ita.co.th/wp-content/uploads/2026/03/Amphenol_Power_Cable-Connector_Mounts.pdf','https://www.aph-ita.co.th/product/hpt-3-mdw/');
