INSERT INTO products (id,slug,name,sku,short_description,description,price,regular_price,currency,in_stock,is_featured,datasheet_url,wp_permalink) VALUES (11645,'rjd2203-0050','RJD2203-0050 – หัวแปลงสัญญาณ Dante แบบรับเข้า 2 ช่องสัญญาณ','หัวแปลงสัญญาณ Dante แบบรับเข้า 2 ช่องสัญญาณ','Amphe-Dante Adapters หัวแปลงสัญญาณ Dante เป็นอนาล็อก แบบรับเข้า/ส่งออก 1 และ 2 ช่องสัญญาณ ลดจำนวนสายสัญญาณในงานติดตั้ง และเชื่อมต่อระบบเสียงผ่านเครือข่ายได้ทันที…','<p>Amphe-Dante Adapters หัวแปลงสัญญาณ Dante เป็นอนาล็อก แบบรับเข้า/ส่งออก 1 และ 2 ช่องสัญญาณ ลดจำนวนสายสัญญาณในงานติดตั้ง และเชื่อมต่อระบบเสียงผ่านเครือข่ายได้ทันที</p><p><strong>ซีรีส์:</strong> Amphe-Dante Adapters</p><h3>คุณสมบัติเด่น</h3><ul><li>แปลง Dante เป็นอนาล็อก และอนาล็อกเป็น Dante</li><li>มีให้เลือก 1 และ 2 ช่องสัญญาณ</li><li>เชื่อมต่อผ่าน PoE เพียงเส้นเดียว</li><li>เหมาะกับงานติดตั้งระบบเสียงเครือข่าย</li></ul><p class="muted">ข้อมูลเพิ่มเติมและแบบวาด (Drawing) / ไฟล์ 3D: หัวแปลงสัญญาณ Dante แบบรับเข้า 2 ช่องสัญญาณ — ดูได้จากแคตตาล็อกสินค้าด้านล่าง</p>',0,0,'THB',1,1,'https://www.aph-ita.co.th/wp-content/uploads/2026/03/Amphenol_Dante.pdf','https://www.aph-ita.co.th/product/rjd2203-0050/');
