INSERT INTO products (id,slug,name,sku,short_description,description,price,regular_price,currency,in_stock,is_featured,datasheet_url,wp_permalink) VALUES (16003,'xlrnet-ip65-range-vuueb','XLRnet IP65 Range – VUUEB','VUUEB','XLRnet คือหัวต่ออีเทอร์เน็ต RJ45 รูปแบบ XLR ของ Amphenol ตัวเล็กแต่ได้สัญญานคม เชื่อมต่อได้มั่นคงกว่าหัวต่อ RJ45 ทั่วไป เหมาะกับงานเสียง–ภาพแบบเครือข่าย และงานเวทีที่ต้องการความเชื…','<p>XLRnet คือหัวต่ออีเทอร์เน็ต RJ45 รูปแบบ XLR ของ Amphenol ตัวเล็กแต่ได้สัญญานคม เชื่อมต่อได้มั่นคงกว่าหัวต่อ RJ45 ทั่วไป เหมาะกับงานเสียง–ภาพแบบเครือข่าย และงานเวทีที่ต้องการความเชื่อถือได้</p><p><strong>ซีรีส์:</strong> Ethernet</p><h3>คุณสมบัติเด่น</h3><ul><li>หัวต่อ RJ45 ในรูปแบบ XLR ล็อกแน่น</li><li>รองรับ CAT5E / CAT6</li><li>มีรุ่น IP65 กันน้ำ</li><li>ตัวเครื่องโลหะกันสัญญาณรบกวน</li></ul><p class="muted">ข้อมูลเพิ่มเติมและแบบวาด (Drawing) / ไฟล์ 3D: VUUEB — ดูได้จากแคตตาล็อกสินค้าด้านล่าง</p>',0,0,'THB',1,1,'https://www.aph-ita.co.th/wp-content/uploads/2026/03/Amphenol_Ethernet_Cable_Connectors.pdf','https://www.aph-ita.co.th/product/xlrnet-ip65-range-vuueb/');
