INSERT INTO products (id,slug,name,sku,short_description,description,price,regular_price,currency,in_stock,is_featured,datasheet_url,wp_permalink) VALUES (16918,'iec268','IEC268','IEC268','หัวต่อ XLR ของ Amphenol สำหรับงานเสียงมืออาชีพ ทั้งแบบตัวผู้ (Male) และตัวเมีย (Female) พร้อมให้เลือกหลายซีรีส์ ตั้งแต่ AC Series สำหรับงานติดตั้ง ไปจนถึง AX Series สำหรับงานสายสัญ…','<p>หัวต่อ XLR ของ Amphenol สำหรับงานเสียงมืออาชีพ ทั้งแบบตัวผู้ (Male) และตัวเมีย (Female) พร้อมให้เลือกหลายซีรีส์ ตั้งแต่ AC Series สำหรับงานติดตั้ง ไปจนถึง AX Series สำหรับงานสายสัญญาณ และรุ่น IP65 สำหรับงานกลางแจ้ง</p><p><strong>ซีรีส์:</strong> XLR</p><h3>คุณสมบัติเด่น</h3><ul><li>ขั้วสัมผัสคุณภาพสูงทองแดงชุบเงิน</li><li>มีทั้งงานบัดกรี (Solder) และงาน PCB</li><li>ตัวเรือนโลหะทนทาน พร้อมตัวล็อกแบบกด</li><li>มีรุ่นกันน้ำ IP65 สำหรับงานกลางแจ้ง</li></ul><p class="muted">ข้อมูลเพิ่มเติมและแบบวาด (Drawing) / ไฟล์ 3D: IEC268 — ดูได้จากแคตตาล็อกสินค้าด้านล่าง</p>',0,0,'THB',1,0,'https://www.aph-ita.co.th/wp-content/uploads/2026/03/Amphenol_XLR_3.pdf','https://www.aph-ita.co.th/product/iec268/');
