INSERT INTO posts (id,slug,title,excerpt,image_url,category,kind,published_at) VALUES (11781,'amphenol-เสร็จสิ้นการเข้าซื้อกิจการ-ccs-จาก-commscope','Amphenol เสร็จสิ้นการเข้าซื้อกิจการ CCS จาก CommScope','Amphenol Corporation ประกาศเสร็จสิ้นการเข้าซื้อกิจการ Connectivity and Cable Solutions (CCS) จาก CommScope เสริมความแข็งแกร่งในกลุ่มงานโครงข่ายและดาต้าเซ็นเตอร์','https://www.aph-ita.co.th/wp-content/uploads/2026/07/news-768x432.webp','News','news','2026-07-28 04:01:44');
INSERT INTO posts (id,slug,title,excerpt,image_url,category,kind,published_at) VALUES (1979,'rca-connectors-m-series','RCA CONNECTORS – M SERIES: มาตรฐานการเชื่อมต่อเสียงสำหรับระบบ Audio/Video','หัวต่อ RCA ซีรีส์ M จาก Amphenol ออกแบบสำหรับงานติดตั้งทั้งในสตูดิโอและงานอีเวนต์ เลือกวัสดุตัวเรือนที่ทนทาน พร้อมการป้องกันสัญญาณรบกวนได้อย่างมีประสิทธิภาพ','https://www.aph-ita.co.th/wp-content/uploads/2022/12/how-to-choose-a-hi-fi-stereo-system-entry-header-opt.jpg','RCA','article','2022-12-13 14:55:19');
INSERT INTO posts (id,slug,title,excerpt,image_url,category,kind,published_at) VALUES (2023,'3-5-mm-เชื่อมต่อจากมือถือ-ด้วย-k-series','3.5 mm เชื่อมต่อจากมือถือ ด้วย K Series','การเชื่อมต่อสัญญาณเสียงจากมือถือหรือแท็บเล็ตเข้ากับมิกเซอร์ทำได้ง่ายขึ้นด้วยหัวต่อ K Series ช่วยให้สัญญาณเสียงต้นทางเสถียร และมีความเพี้ยนต่ำ','https://www.aph-ita.co.th/wp-content/uploads/2022/12/best-gaming-laptop-model-entry-header-opt.jpg','1/4" & 3.5 mm','article','2022-12-13 15:15:11');
INSERT INTO posts (id,slug,title,excerpt,image_url,category,kind,published_at) VALUES (1814,'1-4-phone-jack','1/4″ Phone Jack','ทำความรู้จักหัวต่อ Phone Jack ขนาด 1/4 นิ้ว ที่ใช้ในระบบเครื่องเสียงมืออาชีพ ตั้งแต่ปลั๊ก TRS ไปจนถึง TS สำหรับงานดนตรี','https://www.aph-ita.co.th/wp-content/uploads/2026/01/1-4-parent_cover.jpg','1/4" & 3.5 mm','article','2022-12-13 12:27:12');
INSERT INTO posts (id,slug,title,excerpt,image_url,category,kind,published_at) VALUES (1780,'loudspeaker-connectors-sp-series','LOUDSPEAKER CONNECTORS – SP SERIES: โซลูชั่นมาตรฐานสำหรับระบบเสียงมืออาชีพ','ซีรีส์ SP เป็นหัวต่อลำโพง (Loudspeaker connector) ให้เลือกทั้งแบบ 2 หรือ 4 ขั้ว ตัวเรือน Thermoplastic ทนทาน พร้อมขั้วสัมผัสกระแสสูง','https://www.aph-ita.co.th/wp-content/uploads/2022/12/cameras-for-street-photography-entry-header-opt.jpg','Loudspeaker','article','2022-12-13 12:11:30');
INSERT INTO posts (id,slug,title,excerpt,image_url,category,kind,published_at) VALUES (1717,'xlr-cable-connectors-ax-series','XLR CABLE CONNECTORS – AX SERIES: มาตรฐานใหม่ของการเชื่อมต่อสัญญาณเสียงคุณภาพสูง','ซีรีส์ AX ยกระดับความทนทานและการยึดเกาะของหัวต่อ XLR ให้แน่นหนาขึ้น ลดการหลุดระหว่างใช้งาน พร้อมคุณภาพการส่งสัญญาณระดับสตูดิโอ','https://www.aph-ita.co.th/wp-content/uploads/2022/12/3-minimalist-desk-setups-entry-header-opt.jpg','XLR','article','2022-12-12 15:58:17');
INSERT INTO posts (id,slug,title,excerpt,image_url,category,kind,published_at) VALUES (2024,'delivery-and-return-policy','การจัดส่งและการคืนสินค้า','จัดส่งฟรีทั่วประเทศเมื่อสั่งซื้อครบตามเงื่อนไข โดยขนส่งชั้นนำ ตรวจสอบสินค้าได้ก่อนรับ และมีนโยบายคืนสินค้าภายใน 7 วัน','https://www.aph-ita.co.th/wp-content/uploads/2026/08/Delivery.png','บริการ','news','2022-12-10 09:00:00');
